mapper.select:
SELECT * FROM (SELECT M.*, ROW_NUMBER() OVER (ORDER BY M.UPDATED_AT DESC, M.ID DESC) RN
FROM BUSINESS_MATERIAL_INTAKE M WHERE M.STATUS = 'PARSED'
AND M.ACTOR_ID = #{actorId}
AND NOT EXISTS (
    SELECT 1 FROM PROCUREMENT_DEMAND D WHERE D.DELETED = 0
    AND (D.SOURCE_PROJECT_ID = M.ID OR EXISTS (
        SELECT 1 FROM PROCUREMENT_MATERIAL_LINK L WHERE L.DEMAND_ID = D.ID AND L.MATERIAL_ID = M.ID
    ) OR EXISTS (
        SELECT 1 FROM PROCUREMENT_DEMAND_MATERIAL L WHERE L.DEMAND_ID = D.ID AND L.MATERIAL_ID = M.ID
    ))
)

    AND (INSTR(M.PROJECT_NAME, #{keyword}) > 0 OR INSTR(M.FILE_NAME, #{keyword}) > 0)
) WHERE RN <= #{limit} ORDER BY RN

SELECT * FROM (SELECT M.*, ROW_NUMBER() OVER (ORDER BY CREATED_AT DESC, ID DESC) RN
FROM BUSINESS_MATERIAL_INTAKE M WHERE ACTOR_ID = #{actorId}
AND (ERROR_CODE IS NULL OR ERROR_CODE NOT IN ('MATERIAL_CALL_TIMEOUT','MATERIAL_TIME_LIMIT','MATERIAL_QUEUE_TIMEOUT','MATERIAL_CALL_TIMEOUT_CLEANED','MATERIAL_TIME_LIMIT_CLEANED','MATERIAL_QUEUE_TIMEOUT_CLEANED'))) WHERE RN <= #{limit} ORDER BY RN
